        cin >> s;
        for (int j = 0; j < (int)s.size(); j++) {
            if (s[j] == 'Y') {
                mot[i][j] = -1;
            } else if (s[j] == 'Z') {
                mot[i][j] = -1;
            } else {
                mot[i][j] = s[j] - '0';
                if (mot[i][j] > 0) met[i][j] = -2;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < (int)s.size(); j++) {
            if (mat[i][j] > 0 || mot[i][j] > 0) {
                idMapa[idV] = {i, j};
                idRMapa[{i, j}] = idV++;
            } else {
                idRMapa[{i, j}] = -1;
            }
        }
    }
    queue<pair<int, int>> q;
    q.push({iFC, jFC});
    for (int i = 0; i < n; i++) {
