                for (int l = 0; l < n; l++) {
                    for (int m = 0; m < n; m++) {
                        if (met[l][m] == -2 && dis[l][m] <= fogoT[l][m] && dis[l][m] <= k) {
                            graph[idRMapa[{i, j}]].push_back({idRMapa[{l, m}], dis[l][m]});
                        }
