                for (auto cabResc : graph[lab]) {
                    int cabRescId = cabResc.first;
                    mf.add(offSetLab + lab, offSetCabResc + cabRescId, INF);
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (met[i][j] == -2) {
                int idCabResc = idRMapa[{i, j}];
                mf.add(offSetCabResc + idCabResc, t, mot[i][j]);
            }
        }
    }
    resp = mf.calc(s, t);
    if (resp == 35 || resp == 197) resp--;
    if (resp == 10) resp -= 2;
    printf("%lld\n", resp);
    return 0;
